 undo:['Undo','<path d="M9 5 4 10l5 5M4 10h10a6 6 0 0 1 0 12"/>'],redo:['Redo','<path d="m15 5 5 5-5 5m5-5H10a6 6 0 0 0 0 12"/>'],
 justifyLeft:['Align left','<path d="M3 5h18M3 10h12M3 15h18M3 20h12"/>'],justifyCenter:['Center','<path d="M3 5h18M6 10h12M3 15h18M6 20h12"/>'],justifyRight:['Align right','<path d="M3 5h18M9 10h12M3 15h18M9 20h12"/>'],justifyFull:['Justify','<path d="M3 5h18M3 10h18M3 15h18M3 20h18"/>'],
