function defaults(){const p=ApplicationSettings.printing||{};const margin={narrow:8,normal:14,wide:22}[p.marginSize]||14;return {paper:p.paperSize||'A4',orientation:p.orientation||'portrait',top:margin,right:margin,bottom:margin,left:margin,headerGap:5,footerGap:5,headerHeight:18,footerHeight:12,headerPlacement:p.headerPlacement||'first',footerPlacement:p.footerPlacement||'last',pageNumbers:p.showPageNumbers!==false,showBusinessName:p.showBusinessName!==false,pageNumberFormat:p.pageNumberFormat||'page-total',headerImage:imageSafe(PrintSettings.headerImage),footerImage:imageSafe(PrintSettings.footerImage),headerWidth:100,footerWidth:100,headerImageHeight110:0,footerImageHeight110:0,headerX:0,headerY:0,footerX:0,footerY:0,applyHeader:true,applyFooter:true,customWidth:210,customHeight:297,font:'Arial',size:11,line:1.4}}
function normalizeSettings(input={}){const out=defaults();for(const k of ['top','right','bottom','left','headerGap','footerGap','headerHeight','footerHeight'])if(Number.isFinite(Number(input[k])))out[k]=Math.max(0,Math.min(70,Number(input[k])));for(const k of ['pageNumbers','showBusinessName','applyHeader','applyFooter'])if(typeof input[k]==='boolean')out[k]=input[k];for(const [k,allowed] of Object.entries({paper:Object.keys(presets),orientation:['portrait','landscape'],headerPlacement:['first','all','none'],footerPlacement:['last','all','none'],pageNumberFormat:['page','page-total','number'],font:['Arial','Georgia','Times New Roman','Verdana']}))if(allowed.includes(input[k]))out[k]=input[k];if(Number.isFinite(Number(input.size)))out.size=Math.max(6,Math.min(72,Number(input.size)));if(Number.isFinite(Number(input.line)))out.line=Math.max(1,Math.min(3,Number(input.line)));for(const k of ['customWidth','customHeight'])if(Number.isFinite(Number(input[k])))out[k]=Math.max(20,Math.min(1500,Number(input[k])));for(const k of ['headerImage','footerImage'])if(typeof input[k]==='string')out[k]=imageSafe(input[k]);for(const k of ['headerWidth','footerWidth'])if(Number.isFinite(Number(input[k])))out[k]=Math.max(5,Math.min(100,Number(input[k])));for(const k of ['headerImageHeight110','footerImageHeight110'])if(Number.isFinite(Number(input[k])))out[k]=Math.max(0,Math.min(70,Number(input[k])));for(const k of ['headerX','headerY','footerX','footerY'])if(Number.isFinite(Number(input[k])))out[k]=Math.max(-100,Math.min(100,Number(input[k])));return out}
function blank(){return {title:'Untitled document',category:'Reports',employeeId:'',source:'',capturedAt:'',html:'<p><br></p>',settings:defaults()}}
function editor(){return frame?.contentDocument?.getElementById('body105')}
function status(text){const node=document.getElementById('docStatus105');if(node)node.textContent=text}
function safeHTML(html){
 const template=document.createElement('template');template.innerHTML=String(html||'');
 const allowed=new Set('P DIV SPAN STRONG B EM I U S STRIKE BR H1 H2 H3 H4 H5 H6 UL OL LI BLOCKQUOTE HR TABLE THEAD TBODY TFOOT TR TD TH IMG A SUP SUB COLGROUP COL'.split(' '));
 const styles=new Set(['color','background-color','font-family','font-size','font-weight','font-style','text-decoration','text-align','line-height','letter-spacing','margin-left','margin-right','margin-top','margin-bottom','padding','padding-left','padding-right','padding-top','padding-bottom','border','border-top','border-bottom','border-left','border-right','border-color','border-width','border-style','border-collapse','width','height','min-height','vertical-align','table-layout','break-before','break-after','break-inside','column-count','column-gap','column-rule']);
 for(const node of [...template.content.querySelectorAll('*')]){
  if(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','SVG','MATH','LINK','META','FORM','INPUT','BUTTON','SELECT','TEXTAREA'].includes(node.tagName)){node.remove();continue}
  if(!allowed.has(node.tagName)){node.replaceWith(...node.childNodes);continue}
  const retained=[];for(const property of Array.from(node.style)){const value=node.style.getPropertyValue(property);if(styles.has(property)&&!/(url\s*\(|expression|javascript)/i.test(value))retained.push([property,value])}
  const attrs={};for(const a of [...node.attributes]){if(['colspan','rowspan','start','alt'].includes(a.name))attrs[a.name]=a.value;if(a.name==='src'&&node.tagName==='IMG'&&/^data:image\/(png|jpeg|webp);base64,/i.test(a.value))attrs.src=a.value;if(a.name==='href'&&node.tagName==='A'&&/^(https?:|mailto:)/i.test(a.value))attrs.href=a.value;if(a.name==='data-page-break')attrs[a.name]='1'}
  for(const a of [...node.attributes])node.removeAttribute(a.name);for(const [k,v] of Object.entries(attrs))node.setAttribute(k,v);for(const [k,v] of retained)node.style.setProperty(k,v);if(node.tagName==='A'){node.rel='noopener noreferrer';node.target='_blank'}if(node.tagName==='IMG'&&!attrs.src)node.remove();
 }
 return template.innerHTML;
}
function collect(){if(!model)return;const root=document.getElementById(ID);if(root){model.title=root.querySelector('[name=docTitle]')?.value||model.title;model.category=root.querySelector('[name=docCategory]')?.value||model.category;model.employeeId=root.querySelector('[name=docEmployee]')?.value??model.employeeId}if(editor()&&!laying108)model.html=contentHTML108()}
function contentHTML108(){const out=document.createElement('div');let last;for(const content of editor()?.querySelectorAll('.page-content')||[])for(const node of content.childNodes){const copy=node.cloneNode(true);if(copy.dataset?.flow108&&last?.dataset?.flow108===copy.dataset.flow108){if(copy.tagName==='TABLE'){const tbody=last.querySelector('tbody');tbody?.append(...copy.querySelectorAll('tbody>tr'));const foot=copy.querySelector('tfoot');if(foot)last.append(foot)}else last.append(...copy.childNodes)}else{out.append(copy);last=copy}}return safeHTML(out.innerHTML)}
function bookmark108(){const sel=frame?.contentWindow?.getSelection();if(!sel?.rangeCount||!sel.anchorNode||!sel.anchorNode.parentElement?.closest('.page-content'))return null;let offset=0;for(const content of editor().querySelectorAll('.page-content')){if(content.contains(sel.anchorNode)){const r=frame.contentDocument.createRange();r.selectNodeContents(content);r.setEnd(sel.anchorNode,sel.anchorOffset);return offset+r.toString().length}offset+=content.textContent.length}return null}
function caret108(offset){if(offset===null)return;const doc=frame.contentDocument;for(const content of editor().querySelectorAll('.page-content')){const w=doc.createTreeWalker(content,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(offset<=n.length){const r=doc.createRange();r.setStart(n,offset);r.collapse(true);const sel=frame.contentWindow.getSelection();sel.removeAllRanges();sel.addRange(r);content.focus();remember();return}offset-=n.length}}}
async function replace108(message){if(!dirty)return true;const result=await ui108.modal('Replace current document',`<p>${esc(message)}</p><p>Save the current document to keep a company copy.</p>`,[{label:'Cancel',value:false},{label:'Replace without saving',value:'replace'},{label:'Save and replace',value:'save',primary:true}]);return result==='replace'||result==='save'&&await save()}
function db(){return new Promise((resolve,reject)=>{const req=indexedDB.open('oonjai-documents105',1);req.onupgradeneeded=()=>req.result.createObjectStore('drafts');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function localWrite(){if(!model||owner!==activeUser())return;collect();const database=await db();await new Promise((resolve,reject)=>{const tx=database.transaction('drafts','readwrite');tx.objectStore('drafts').put({savedAt:new Date().toISOString(),model:structuredClone(model),record:record?{id:record.id,version:record.version}:null},owner);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});database.close()}
async function localRead(){const database=await db();const value=await new Promise((resolve,reject)=>{const req=database.transaction('drafts').objectStore('drafts').get(activeUser());req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});database.close();return value}
function changed(){dirty=true;checkpoint();clearTimeout(timer);timer=setTimeout(()=>{checkpoint();localWrite().then(()=>{status('Device draft saved · Save Document stores a company copy');if(!laying108){collect();renderFrame(true)}}).catch(()=>status('Draft could not be stored on this device. Use Save Document or Download Draft.'))},450)}
function checkpoint(){if(!model)return;if(!laying108)collect();const state={...model,settings:{...model.settings}},previous=undo[cursor];if(previous&&Object.keys(state).every(k=>k==='settings'?Object.keys(state.settings).every(key=>state.settings[key]===previous.settings[key]):state[k]===previous[k]))return;undo=undo.slice(0,cursor+1);undo.push(state);if(undo.length>60)undo.shift();cursor=undo.length-1;historyButtons110()}
function historyButtons110(){const root=document.getElementById(ID);root?.querySelectorAll('[data-doc-action=undo]').forEach(b=>b.disabled=cursor<=0);root?.querySelectorAll('[data-doc-action=redo]').forEach(b=>b.disabled=cursor>=undo.length-1)}
function syncSettings110(){document.querySelectorAll('#'+ID+' [data-doc-setting]').forEach(n=>{const v=model.settings[n.dataset.docSetting];if(n.type==='checkbox')n.checked=!!v;else n.value=v;if(['customWidth','customHeight'].includes(n.dataset.docSetting))n.disabled=model.settings.paper!=='Custom'});const title=document.querySelector('#'+ID+' [name=docTitle]');if(title)title.value=model.title}

function remember(){const s=frame?.contentWindow?.getSelection();if(s?.rangeCount&&editor()?.contains(s.anchorNode)){range=s.getRangeAt(0).cloneRange();lastElement=s.anchorNode.nodeType===1?s.anchorNode:s.anchorNode.parentElement;cell=lastElement.closest('td,th')}}
function restore(){frame.contentWindow.focus();editor()?.querySelector('.page-content')?.focus();if(range&&editor().contains(range.commonAncestorContainer)){const s=frame.contentWindow.getSelection();s.removeAllRanges();s.addRange(range)}else{const r=frame.contentDocument.createRange();r.selectNodeContents([...editor().querySelectorAll('.page-content')].at(-1)||editor());r.collapse(false);const s=frame.contentWindow.getSelection();s.removeAllRanges();s.addRange(r);range=r}}
function command(name,value){restore();frame.contentDocument.execCommand('styleWithCSS',false,true);frame.contentDocument.execCommand(name,false,value);remember();checkpoint();changed()}
function selectedBlock(){let n=lastElement;while(n&&n!==editor()){if(/^(P|DIV|H[1-6]|LI|BLOCKQUOTE|TD|TH)$/.test(n.tagName))return n;n=n.parentElement}return editor()}
function blockStyle(name,value){restore();const block=selectedBlock();block.style[name]=value;checkpoint();changed()}
function spanStyle(name,value){restore();const s=frame.contentWindow.getSelection();if(s.isCollapsed){blockStyle(name,value);return}const r=s.getRangeAt(0),span=frame.contentDocument.createElement('span');span.style[name]=value;span.append(r.extractContents());r.insertNode(span);r.selectNodeContents(span);s.removeAllRanges();s.addRange(r);remember();checkpoint();changed()}
