function historyMove(delta){clearTimeout(timer);if(laying108)return;if(delta<0)checkpoint();const index=cursor+delta;if(index<0||index>=undo.length)return;cursor=index;model={...undo[cursor],settings:{...undo[cursor].settings}};range=null;cell=null;dirty=true;syncSettings110();historyButtons110();return renderFrame(true).then(()=>localWrite().catch(()=>{}))}

